  function appearanceView(){const color=state.themeColor||'#658d22';return `<section class="appearance-card"><div class="section-head"><div><h2>Appearance</h2><p class="quiet">A color that feels like you.</p></div><button class="text-button" data-action="theme" data-color="#658d22">Reset to Kiwi</button></div><div class="theme-palettes" role="group" aria-label="Color themes">${[['#658d22','Kiwi'],['#258267','Forest'],['#249b97','Teal'],['#347da5','Ocean'],['#4164ce','Cobalt'],['#6751b5','Iris'],['#9060b3','Lilac'],['#a64a69','Rose'],['#c86e4b','Peach'],['#b77521','Amber'],['#bd374d','Cherry'],['#576275','Slate']].map(([hex,name])=>`<button class="theme-choice ${color===hex?'selected':''}" data-action="theme" data-color="${hex}" aria-label="${name} theme" aria-pressed="${color===hex}"><span style="background:${hex}">${color===hex?icon('check'):''}</span>${name}</button>`).join('')}</div><div class="custom-color-row"><label for="theme-color">Your own color</label><div><input id="theme-color" type="color" value="${esc(color)}" aria-label="Choose custom color"><input id="theme-hex" type="text" value="${esc(color.toUpperCase())}" maxlength="7" pattern="#[0-9a-fA-F]{6}" aria-label="Custom color hex" spellcheck="false"></div></div><div class="theme-preview"><span class="theme-preview-ring">${icon('clock')}</span><div><strong>Your time. Your palette.</strong><span class="progress-track"><i style="width:68%"></i></span></div><span class="theme-preview-tag">Preview</span></div><p class="field-help">Changes save automatically on this device. Light and dark shades are balanced to keep text readable.</p></section>`;}
