  function applyChecklistStatus(s,t,value){if(value==='tomorrow'){const tomorrow=new Date();tomorrow.setDate(tomorrow.getDate()+1);C.setItemStatus(s,t,'todo');C.resolveUnfinished(s,t,'move',C.dayKey(tomorrow));if(t.habitId){const entry=C.habitEntry(s,t.habitId,C.dayKey(tomorrow),true);entry.status='todo';s.habitChecks=s.habitChecks.filter(c=>!(c.habitId===t.habitId&&c.date===C.dayKey(tomorrow)));}}else if(value==='cancel'){C.setItemStatus(s,t,'todo');C.resolveUnfinished(s,t,'let_go');}else C.setItemStatus(s,t,value);}
  function checklistStatus(t,value){const date=t.habitId?t.date:C.dayKey(Date.now()),minutes=C.itemDayMinutes(state,t,date),label=date===C.dayKey(Date.now())?'Minutes spent today':'Minutes for '+dateLabel(date),statusLabel={todo:'To do',in_progress:'In progress',done:'Done',tomorrow:'Move to tomorrow',cancel:'Cancel'}[value];render();sheet('Record your time','<p class="status-time-task">'+esc(t.title)+'</p><p class="field-help">Change status to <strong>'+esc(statusLabel)+'</strong>.</p>'+input(label,'minutes','number',minutes?Number(minutes.toFixed(1)):'','min="0" max="1440" step="0.1" inputmode="decimal" placeholder="e.g. 25" id="status-minutes"')+'<p class="field-help">Enter the total for this day. Already recorded: '+duration(minutes)+'. Saving replaces this day’s minutes and updates Insights.</p><button type="button" class="text-button" data-action="status-only">Change status without editing time</button>',{type:'status-time',item:t,status:value,date},'Save');}
