    if(e.target.dataset?.longTaskStage!==undefined){mutate(s=>{const t=s.projectTasks.find(t=>t.id===e.target.dataset.id);if(!t)return;const p=s.projects.find(p=>p.id===t.projectId);if(e.target.value&&!p.stages.some(x=>x.id===e.target.value))throw new Error('Choose a stage in this project.');t.stageId=e.target.value||null;s.tasks.filter(x=>x.projectTaskId===t.id).forEach(x=>C.updateTask(s,x,{stageId:t.stageId}));});return;}

    if(e.target.dataset?.stageStatus!==undefined){mutate(s=>{const p=s.projects.find(p=>p.id===e.target.dataset.project),stage=p?.stages.find(x=>x.id===e.target.dataset.id);if(stage){stage.status=e.target.value;stage.done=e.target.value==='done';}});return;}
    if(e.target.dataset?.stageSelect!==undefined){const form=e.target.closest('form'),stage=e.target.value,p=state.projects.find(p=>p.stages.some(s=>s.id===stage));if(p)form.querySelector('[name="projectId"]').value=p.id;return;}
    if(e.target.dataset?.projectSelect!==undefined){const form=e.target.closest('form'),select=form.querySelector('[name="stageId"]');if(select&&!state.projects.find(p=>p.id===e.target.value)?.stages.some(s=>s.id===select.value))select.value='';return;}

    if(e.target.id==='event-repeat'){const field=$('#event-repeat-days');if(field)field.hidden=e.target.value!=='custom';return;}
    if(e.target.id==='calendar-date'){try{day=C.validDay(e.target.value);eventDraft=null;render();}catch{}return;}
    if(e.target.dataset?.checkStatus!==undefined||e.target.dataset?.checkToggle!==undefined){const t=resolveItem(e.target.dataset);if(t)checklistStatus(t,e.target.dataset.checkToggle!==undefined?(e.target.checked?'done':'todo'):e.target.value);return;}
